import itertools,json
jobs='ABCDE'
slot={'A':[0,1,4,11,3],'B':[2,3,3,2,5],'C':[4,8,2,10,8],'D':[3,2,11,3,4],'E':[10,6,10,10,4]}
tmat=[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]
t={(a,b):tmat[i][j] for i,a in enumerate(jobs) for j,b in enumerate(jobs)}
def nominal(p):return sum(slot[a][i] for i,a in enumerate(p))+sum(t[a,b] for a,b in zip(p,p[1:]))
def cost(p,incident,swapped):
 pos={a:i+1 for i,a in enumerate(p)}
 if pos['A']>pos['D']:return None
 if incident=='rain':
  if pos['D']==1 or pos['A']==1:return None
  penalty=6*max(0,pos['C']-1)
 elif incident=='road':
  if pos['C']==4 or pos['E']==2:return None
  penalty=6*max(0,pos['D']-3)
 else:
  if pos['A']==1 or pos['B']==1:return None
  penalty=10*max(0,pos['E']-2)
 return nominal(p)+penalty+swapped
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'):continue
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i];neighbors.append((tuple(q),1))
 repairs={};costs={}
 for incident in ['rain','road','lift']:
  valid=[(c,''.join(q)) for q,s in neighbors if (c:=cost(q,incident,s)) is not None]
  if not valid:break
  costs[incident],repairs[incident]=min(valid)
 if len(costs)==3:results.append((nominal(p)+max(costs.values()),''.join(p),repairs,costs,nominal(p)))
results.sort()
best=results[0]
print(json.dumps({'roster':best[1],'score':best[0],'repairs':best[2],'repair_costs':best[3],'feasible_count':len(results),'next_score':min(x[0] for x in results if x[0]>best[0])}))
print('best',best,'optima',sum(x[0]==best[0] for x in results),'publications checked',60)

