import itertools,json
start='AECBD';jobs='ABCDE'
s={'A':[0,1,4,11,3],'B':[2,3,3,2,5],'C':[4,8,2,10,8],'D':[3,2,11,3,4],'E':[10,6,10,10,4]}
m=[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]
def distance(p):
 perm=[start.index(a) for a in p]; seen=set();cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1;j=i
   while j not in seen:seen.add(j);j=perm[j]
 return 5-cycles
classes={i:[] for i in range(3)}
for p in itertools.permutations(jobs):
 d=distance(p)
 if d>2:continue
 pos={a:i+1 for i,a in enumerate(p)}
 if pos['A']>=pos['D'] or pos['D']==1 or pos['A']==1 or pos['B']==4:continue
 nominal=sum(s[a][i] for i,a in enumerate(p))+sum(m[jobs.index(a)][jobs.index(b)] for a,b in zip(p,p[1:]))
 cost=nominal+6*(pos['C']-1)+d+(4 if d==2 else 0)
 classes[d].append((cost,''.join(p)))
best=min(x for v in classes.values() for x in v)
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(k):min(v)[0] if v else None for k,v in classes.items()},'feasible_by_swaps':{str(k):len(v) for k,v in classes.items()}}))
print({k:sorted(v) for k,v in classes.items()})

